const daily = (msg.payload && msg.payload.daily) || {};
if (!daily.temperature_2m_max || !daily.temperature_2m_min) {
    node.error('The forecast service did not answer with a forecast', msg);
    return null;
}
const rain = daily.precipitation_probability_max ? daily.precipitation_probability_max[0] : null;
msg.payload = 'Today: ' + Math.round(daily.temperature_2m_min[0]) + ' to ' + Math.round(daily.temperature_2m_max[0]) + ' C'
    + (rain === null ? '.' : ', chance of rain ' + rain + '%.');
return msg;
